package tn.esprit.partnerintelligence.entity;
import jakarta.persistence.*;import java.time.Instant;@Entity public class RecommendationDecision { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long recommendationId; private String decision; private String reviewer; @Column(length=1000) private String comment; private Instant decidedAt=Instant.now(); public Long getId(){return id;} public void setId(Long id){this.id=id;} public Long getRecommendationId(){return recommendationId;} public void setRecommendationId(Long recommendationId){this.recommendationId=recommendationId;} public String getDecision(){return decision;} public void setDecision(String decision){this.decision=decision;} public String getReviewer(){return reviewer;} public void setReviewer(String reviewer){this.reviewer=reviewer;} public String getComment(){return comment;} public void setComment(String comment){this.comment=comment;} public Instant getDecidedAt(){return decidedAt;} public void setDecidedAt(Instant decidedAt){this.decidedAt=decidedAt;} }